mapper.select:
select log_id, device_id, sn, product_id, sync_content, sync_status, command_type, create_time, remark
from pms_device_sync_log

    AND device_id = #{deviceId}
    AND sn like concat('%', #{sn}, '%')
    AND sync_status = #{syncStatus}
    AND create_time >= #{beginTime}
    AND create_time <= #{endTime}
    AND create_time >= #{params.beginTime}
    AND create_time <= #{params.endTime}

order by log_id desc
